-- Reverse migration 000018.

-- Remove enhanced hook columns.
ALTER TABLE agent_hook
  DROP COLUMN IF EXISTS timeout_seconds,
  DROP COLUMN IF EXISTS is_async,
  DROP COLUMN IF EXISTS run_once,
  DROP COLUMN IF EXISTS status_message;

-- Remove allowed_tools from skill.
ALTER TABLE skill DROP COLUMN IF EXISTS allowed_tools;

